head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.clickBzProcsNo = "";
scwin.vAcptNo = "";
scwin.vOpenTyp = ""; // R=접수, H = 이력, N : 신규
scwin.vSPOT_ISU_TRD_MKT_TP_CD = "";
// 세션정보를 얻기위한 함수사용

scwin.fn_GetPar, scwin.fn_SetPar;
scwin.fr_SecuGrpId = SECUGRP_ID_SR;

scwin.pSecuGrpId = SECUGRP_ID_SR;
scwin.gIsurCd;
scwin.gComAbbrv;
scwin.gSecugrpId;
scwin.gMktTpCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        const parentWin = $c.lc.fn_GetRecvDocProvider();
        // var parentWin = frame.Provider("../");
        // alert('[parentWin]'+parentWin);
        if (scwin.gIsurCd !== "" && scwin.gIsurCd !== undefined) {
            txb_ISUR_CD.setValue(scwin.gIsurCd);
            txb_COM_NM.setValue(scwin.gComAbbrv);
            scwin.fr_SecuGrpId = scwin.gSecugrpId;
            scwin.vSPOT_ISU_TRD_MKT_TP_CD = scwin.gMktTpCd;
            btn_Search.trigger("onclick");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05800.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            await $c.win.alert("[회사]를 선택하세요.");
            txb_ISUR_CD.focus();
            return;
        } else {
            await scwin.allListSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05800.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF05800.xml", SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, {fileName: "신주인수권증권 발행내역", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05800.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name img_COM_NM_onclick
 * @description img_COM_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_COM_NM_onclick = function() {
    try {
        scwin.fn_GetPar = scwin.getParIsur;
        scwin.fn_SetPar = scwin.setParIsur;

        // "1" :신주상장, "2" :변경상장
        $c.lc.fn_PopFindCorpChrgSW(scwin.fr_SecuGrpId, "1");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05800.img_COM_NM_onclick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            await $c.win.alert("[회사]를 선택하세요.");
            txb_ISUR_CD.focus();
            return;
        }
        await scwin.openDetailMng(-1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05800.btn_New_onclick" });
    }
};

/**
 * @method
 * @name grd_Recv_OnDblClick
 * @description grd_Recv 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Recv_OnDblClick = function(row, colid) {
    try {
        $c.elw.fn_OpenDetailRecv(row);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05800.grd_Recv_OnDblClick" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        await scwin.openDetailMng(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05800.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name dts_Recv_OnLoadError
 * @description dts_Recv 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Recv_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Recv);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05800.dts_Recv_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05800.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Recv_OnLoadCompleted
 * @description dts_Recv 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Recv_OnLoadCompleted = function(rowcount) {
    try {
        edt_TotalCnt_1.setValue("총 " + dts_Recv.getRowCount() + " 건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05800.dts_Recv_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        edt_TotalCnt_2.setValue("총 " + dts_List.getRowCount() + " 건");
        dts_List.setRowPosition(dts_List.getRowCount(), 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05800.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05800.btn_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name recvListSync
 * @description recv List Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.recvListSync = async function() {
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === "1") {
        // 유가경우
        $c.cm.setColumnProp(grd_Recv, "LIST_SCH_STRT_DD", "Show", false);
        url += "?SCREN_ID=" + "ULDSTF05800.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=searchIsuIssChgList&DIV_IDX=" + DIV_IDX_NEW_ISS_SR_RECV_S + "&ISUR_CD=" + txb_ISUR_CD.getValue();
        const sbmOptions = {
            id : "sbm_dts_Recv",
            action : "/Listing.do",
            ref : "",
            target : "dts_Recv=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === "2") {
        // 코스닥인경우
        $c.cm.setColumnProp(grd_Recv, "LIST_SCH_STRT_DD", "Show", true);
        url += "?SCREN_ID=" + "ULDSTF05800.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=searchIsuIssChgList" + "&DIV_IDX=" + DIV_IDX_NEW_ISS_SR_RECV_K + "&ISUR_CD=" + txb_ISUR_CD.getValue();
        const sbmOptions = {
            id : "sbm_dts_Recv",
            action : "/Listing.do",
            ref : "",
            target : "dts_Recv=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF05800.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuIssChgList&DIV_IDX=" + DIV_IDX_NEW_ISS_SWR_HIST + "&ISUR_CD=" + txb_ISUR_CD.getValue() + "&SECUGRP_ID=" + scwin.pSecuGrpId;
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/Listing.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsur
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISUR_CD.getValue(); // 발행기관코드값
    arrPar[1] = txb_COM_NM.getValue(); // 발행기관명
    return arrPar.length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParIsur = async function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].COM_NM);
        scwin.vSPOT_ISU_TRD_MKT_TP_CD = arrPar[0].SPOT_ISU_TRD_MKT_TP_CD;
        await scwin.allListSync();
    }
};

/**
 * @method
 * @name getBzProcsNo
 * @description get Bz Procs No 처리
 * @returns {void}
 * @hidden N
 */
scwin.getBzProcsNo = function() {
    return scwin.clickBzProcsNo;
};

/**
 * @method
 * @name allListSync
 * @description all List Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.allListSync = async function() {
    await scwin.recvListSync();
    await scwin.listSync();
};

/**
 * @method
 * @name setBzProcsNo
 * @description set Bz Procs No 처리
 * @param {*} dsjObj dsjObj
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function(dsjObj, row) {
    scwin.clickBzProcsNo = dsjObj.getCellData(Number(row), "BZ_PROCS_NO");
    // alert("fn_setBzProcsNo():"+clickBzProcsNo);

};

/**
 * @method
 * @name openDetailRecv
 * @description open Detail Recv 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetailRecv = async function(row) {
    scwin.vOpenTyp = "R";
    scwin.setBzProcsNo(dts_Recv, row);
    scwin.vAcptNo = dts_Recv.getCellData(row, "ACPT_NO");
    if (scwin.vAcptNo !== "") {
        await scwin.openPopup();
    }
};

/**
 * @method
 * @name openDetailMng
 * @description open Detail Mng 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetailMng = async function(row) {
    scwin.vAcptNo = ""; // 초기화
    if (row > 0) {
        // 그리드에서 선택시
        scwin.vOpenTyp = "H";
        scwin.setBzProcsNo(dts_List, row);
    } else {
        // 신규버튼 선택시
        scwin.vOpenTyp = "N";
        scwin.clickBzProcsNo = ""; // 초기화

    }
    await scwin.openPopup();
};

/**
 * @method
 * @name openPopup
 * @description open Popup 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openPopup = async function() {
    const options = {
        id: "ULDSTF05801",
        title: "신주인수권증서 신주상장 관리",
        type: "browserPopup",
        width: "870px",
        height: "450px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/lstproc/ULDSTF05801.gfm", options);
};
